    $valid = static function ( $names, $files, $errors ) use ( &$valid, $types, $mime ) {
        if ( is_array( $names ) ) {
            if ( ! is_array( $files ) || ! is_array( $errors ) || array_keys( $names ) !== array_keys( $files ) || array_keys( $names ) !== array_keys( $errors ) ) {
                return false;
